/bin/zsh -lc "python -c \"import pandas as pd,numpy as np; from scipy.optimize import minimize; from scipy.special import expit; d=pd.read_csv('data/nls_ses_processed.csv'); s=d.SES.to_numpy(); b=(d.SAMPLE_RACE=='Black').astype(float).to_numpy(); h=(d.SAMPLE_RACE=='Hispanic').astype(float).to_numpy(); y=d['BA DEGREE COMPLETED'].astype(float).to_numpy();
for cols in [[np.ones(len(d)),s,b,h,s*b],[np.ones(len(d)),s,b,h,s*b,s*h],[np.ones(len(d)),s,b,h,s*b,s*h,s*b*h]]:
 X=np.array(cols).T; f=lambda q:(np.logaddexp(0,X@q)-y*(X@q)).sum(); r=minimize(f,np.zeros(X.shape[1]),method='BFGS'); print(r.x)\""

